"""Tiny prep-ordering helper for small restaurants: estimates what to order from recent usage."""
from statistics import mean

def suggest_order(usage_by_day, on_hand, par_days=2):
    """usage_by_day: {item: [daily units used, ...]}; on_hand: {item: units}."""
    orders = {}
    for item, days in usage_by_day.items():
        target = round(mean(days) * par_days)
        need = max(0, target - on_hand.get(item, 0))
        if need:
            orders[item] = need
    return orders

if __name__ == "__main__":
    usage = {"rice (lb)": [12, 10, 14], "chicken thighs (lb)": [8, 9, 7]}
    stock = {"rice (lb)": 10, "chicken thighs (lb)": 4}
    print(suggest_order(usage, stock))
EOF
